<script setup lang="ts">import {usePropertyStore} from '@/hooks/property';import {continuousDefaults} from '@/continuous-ribbon';const property=usePropertyStore();</script><template><section><h3>连续纸带时钟</h3><p>参考字形展开为一条纸带，再折回新的参考字形。</p><label>配色主题<select :value="property.settings.theme||'red'" @change="property.settings.theme=($event.target as HTMLSelectElement).value"><option value="red">中国红</option><option value="gold">黑金</option><option value="ice">冰蓝</option></select></label><label>路径变形<input type="checkbox" :checked="property.settings.animate!==false" @change="property.settings.animate=($event.target as HTMLInputElement).checked"></label><label>变形速度<select :value="property.settings.duration||1100" @change="property.settings.duration=Number(($event.target as HTMLSelectElement).value)"><option :value="650">快速</option><option :value="1100">标准</option><option :value="1600">舒缓</option></select></label><button @click="property.settings.demoToken=Date.now()">演示展开与折回</button><label>纸带呼吸<input type="checkbox" :checked="property.settings.breath!==false" @change="property.settings.breath=($event.target as HTMLInputElement).checked"></label><label>冒号闪烁<input type="checkbox" :checked="property.settings.blink!==false" @change="property.settings.blink=($event.target as HTMLInputElement).checked"></label><label>显示日期<input type="checkbox" :checked="property.settings.showDate!==false" @change="property.settings.showDate=($event.target as HTMLInputElement).checked"></label><label>图像传输<select :value="property.settings.transport||'compatible'" @change="property.settings.transport=($event.target as HTMLSelectElement).value"><option value="compatible">兼容模式</option><option value="binary">二进制 PNG（实验）</option></select></label><button @click="Object.assign(property.settings,continuousDefaults)">恢复默认</button></section></template><style scoped>section{padding:16px;color:#eee;font:13px 'Microsoft YaHei',sans-serif}label{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:16px 0}p{opacity:.65;line-height:1.7}button,select{padding:7px;background:#35191c;color:#fff;border:1px solid #86535a;border-radius:5px}button{cursor:pointer;margin:5px 0}</style>
